import{_ as t,o as e,c as r,a2 as d}from"./chunks/framework.doxMM-x8.js";const p=JSON.parse('{"title":"产品范围与架构","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/architecture/lab-word","contentType":"concept","prev":false,"next":false},"headers":[],"relativePath":"architecture/lab-word.md","filePath":"architecture/lab-word.md"}'),n={name:"architecture/lab-word.md"};function o(l,a,i,s,c,h){return e(),r("div",null,[...a[0]||(a[0]=[d(`<h1 id="产品范围与架构" tabindex="-1">产品范围与架构 <a class="header-anchor" href="#产品范围与架构" aria-label="Permalink to &quot;产品范围与架构&quot;">​</a></h1><p>Lab Word 的产品目标是实验室数字孪生。当前正式应用提供持久 Lab、独立 Entity、多节点场景、服务器资产库、版本化定义、布局编辑与人工关系登记及后端照明程序。术语见 <a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a>。</p><h2 id="模型与设备的关系" tabindex="-1">模型与设备的关系 <a class="header-anchor" href="#模型与设备的关系" aria-label="Permalink to &quot;模型与设备的关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lab ──登记──&gt; Entity（设备等对象）&lt;──定义── Asset</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 └──由 Scene Node 呈现 &lt;──外观── Asset Representation</span></span></code></pre></div><p>这是当前已建立的 Foundation V1 身份关系：Equipment Model 是三维资产表示，Equipment Instance 是设备类 Entity；Scene Node 的身份与摆放独立于设备身份。同一模型可表示多台设备，同一设备也可有多个节点。登记时固定定义版本及快照；模拟与真实对象保留独立身份，静态对象无需 Binding。</p><h2 id="已有实现与目标接入" tabindex="-1">已有实现与目标接入 <a class="header-anchor" href="#已有实现与目标接入" aria-label="Permalink to &quot;已有实现与目标接入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>当前状态</th><th>后续责任</th></tr></thead><tbody><tr><td>通用应用壳、身份、成员、知识库</td><td>现有应用代码</td><td>为 Lab 提供宿主与共享能力</td></tr><tr><td>Lab 与持久资产库</td><td>Member/Agent 共用世界、布局、关系、文件、照明与温度 API、可靠订阅</td><td>更多设备程序与历史记录</td></tr><tr><td>Lab 导航与登录后默认入口</td><td>已由显式组装接入</td><td>保持宿主和 Lab 职责分离</td></tr><tr><td>Foundation V1</td><td>体验已接受，规格/实施票已发布</td><td>建立持久世界与后端虚拟设备运行</td></tr><tr><td>真实设备与协议接入</td><td>后续范围</td><td>按实际来源增加适配与执行合同</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>选择复用现有 SaaS 底座：Lab 拥有设备与布局业务，Core 保持身份、成员等公共职责。接入点见<a href="./project-structure">项目结构</a>。</p><h2 id="当前呈现层边界" tabindex="-1">当前呈现层边界 <a class="header-anchor" href="#当前呈现层边界" aria-label="Permalink to &quot;当前呈现层边界&quot;">​</a></h2><p>Lab 主入口使用对象目录、多节点场景和 Inspector，保存摆放、实例配置及引用，另一浏览器和 Agent 可读取同一世界。指针变换只编辑 Placement；位于、包含和模拟对应通过显式关系登记保存人工来源，空间关系共同拒绝非法环。独立复制创建新 Entity，多表示和移除节点保留身份；版本冲突保留页面草稿，显式重载后重试，见<a href="./../tutorials/edit-layout">布局教程</a>。定义支持、Binding 实现和当前可执行性分开；无观测时返回未知。照明在后端独立运行，命令接受和实际观测分开，停止保留最后观测，重启中断后需显式启动；见<a href="./../tutorials/backend-lights">照明教程</a>。布局版本与运行态分离；<a href="./../tutorials/reliable-sync">世界订阅</a>提供持久版本、实体属性更新、有界队列、断线快照恢复和现有连接撤权，执行服务就绪与持久能力许可共同决定可操作性。离心任务与历史记录仍由后续切片提供。资产库在 <code>/lab/asset</code> 保留单模型预览；文件由 Core 生命周期保存，Lab 拥有稳定资产与表示引用。</p><p><a href="./../tutorials/continuous-temperature">温度传感器</a>在后端以 1Hz 独立采样。每个属性保留值、单位、来源、时间和质量。心跳不刷新旧测量。停止后保留最后值，并在报告期限后过期。过期推进世界版本，布局草稿不受影响。</p><p>当前实现保持模型原始尺度，并在外部资源依赖、无几何或解码失败时反馈错误、保留前一个可用模型。每个节点独立加载并释放模型资源，选择一个实例不改写其他实例材质；World 快照返回节点及未放置对象引用的资产，模型恢复不依赖目录第一页。</p><p>Three.js 相关代码已随 Lab 页面按需加载，并纳入正式包体预算。预览的构建与软件渲染指标不代表目标硬件性能。</p><h2 id="继续开发" tabindex="-1">继续开发 <a class="header-anchor" href="#继续开发" aria-label="Permalink to &quot;继续开发&quot;">​</a></h2><p>先按<a href="./../guides/lab-viewer">查看器指南</a>观察现有功能。Foundation V1 从<a href="https://github.com/CaiZongyuan/labworld/issues/1" target="_blank" rel="noreferrer">规格 #1</a>及其实施票继续，接手入口为<a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/docs/handoffs/digital-twin-foundation-v1.md" target="_blank" rel="noreferrer">开发交接</a>；职责规则见<a href="./module-boundaries">模块边界</a>。</p><hr><p>源码版本：<code>ddaf175ca215</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/docs/architecture/lab-word.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,17)])])}const u=t(n,[["render",o]]);export{p as __pageData,u as default};
